SELECT c.Name AS Category, COUNT(*) AS ActiveProducts
FROM dbo.Product p
INNER JOIN dbo.Category c ON c.CategoryId = p.CategoryId
WHERE p.IsActive = 1
GROUP BY c.Name
ORDER BY c.Name;
